(() => {
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const ui={form:document.getElementById('formLabel'),count:document.getElementById('emberCount'),fill:document.getElementById('emberFill'),lives:document.getElementById('lifeCount'),goal:document.getElementById('goalTitle'),text:document.getElementById('goalText'),start:document.getElementById('startPanel'),end:document.getElementById('endPanel'),toast:document.getElementById('toast'),flash:document.getElementById('flash')};
let W=1280,H=720,scale=1,dpr=1,camera=0,last=0,started=false,ended=false,muted=false,audio;
const worldEnd=4170,keys={left:false,right:false,jump:false},rng=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const platforms=[{x:0,y:605,w:910},{x:1085,y:605,w:630},{x:1810,y:605,w:620},{x:2520,y:605,w:580},{x:3180,y:605,w:990}, {x:480,y:495,w:165},{x:700,y:420,w:145},{x:1195,y:480,w:145},{x:1435,y:405,w:160},{x:1940,y:485,w:165},{x:2180,y:400,w:150},{x:2670,y:477,w:180},{x:2930,y:400,w:155},{x:3440,y:465,w:175},{x:3700,y:390,w:165}];
const embers=[{x:555,y:450},{x:765,y:374},{x:1260,y:436},{x:1515,y:358},{x:2015,y:440},{x:2250,y:353},{x:2750,y:432},{x:3000,y:355},{x:3525,y:421},{x:3780,y:344}];
const hazards=[{x:810,base:590,range:65,speed:1.05,phase:0},{x:1540,base:590,range:80,speed:.8,phase:2},{x:2250,base:590,range:72,speed:1.15,phase:4},{x:2885,base:590,range:62,speed:.9,phase:1}];
let player,particles=[],decor=[],worldTime=0,toastTimer=0,checkpoint=0;
function fresh(){player={x:100,y:560,vx:0,vy:0,w:34,h:48,form:'human',energy:100,lives:3,ground:false,facing:1,invuln:0,anim:0,checkpoint:0};particles=[];checkpoint=0;embers.forEach(e=>e.taken=false);hazards.forEach(h=>h.active=true);camera=0;ended=false;updateHud()}
function resize(){const rect=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);scale=rect.height/720;W=rect.width/scale;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr*scale,0,0,dpr*scale,0,0)}
window.addEventListener('resize',resize);resize();fresh();
function updateHud(){ui.form.textContent=player.form==='phoenix'?'PHOENIX FORM':'HUMAN FORM';ui.count.textContent=embers.filter(e=>e.taken).length;ui.fill.style.width=`${player.energy}%`;ui.lives.textContent='✦ '.repeat(player.lives).trim()||'—';let n=embers.filter(e=>e.taken).length;ui.goal.textContent=n<6?'Find the six embers':'Reach the Sun Gate';ui.text.textContent=n<6?'The old shrine stirs. Gather its lost fire, then reach the Sun Gate.':'The gate is awake. Carry the last flame to the valley’s edge.'}
function message(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function sound(freq=440,duration=.12,type='sine',vol=.035){if(muted)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function burst(x,y,color,n=15){for(let i=0;i<n;i++)particles.push({x,y,vx:rng(-150,150),vy:rng(-200,45),life:rng(.35,.9),max:.9,size:rng(2,5),color})}
function transform(){if(!started||ended)return;if(player.form==='human'){if(player.energy<20){message('Gather an ember to kindle your wings');sound(120,.12,'square',.02);return}player.form='phoenix';player.vy=Math.min(player.vy,-115);burst(player.x+17,player.y+22,'#ffb457',24);flash();sound(240,.4,'sawtooth',.045);message('The fire remembers you')}else{player.form='human';burst(player.x+17,player.y+20,'#ffc779',13);sound(340,.17,'sine',.03)}updateHud()}
function flash(){ui.flash.classList.remove('on');void ui.flash.offsetWidth;ui.flash.classList.add('on')}
function jump(){if(!started||ended)return;if(player.form==='human'&&player.ground){player.vy=-540;player.ground=false;burst(player.x+17,player.y+47,'#d59d70',5);sound(190,.09,'triangle',.022)}else if(player.form==='phoenix'){player.vy-=220;player.energy=Math.max(0,player.energy-1.6);burst(player.x+17,player.y+38,'#ff9b4c',3);sound(290,.06,'sine',.015)}}
function keydown(e){if(['ArrowLeft','ArrowRight','ArrowUp',' ','Space'].includes(e.key))e.preventDefault();if(e.repeat&&['f','F','Escape'].includes(e.key))return;if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=true;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=true;if(e.key===' '||e.key==='ArrowUp'||e.key==='w'||e.key==='W'){if(!keys.jump)jump();keys.jump=true}if(e.key==='f'||e.key==='F')transform();if(e.key==='Escape'&&started&&!ended)togglePause()}
function keyup(e){if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=false;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=false;if(e.key===' '||e.key==='ArrowUp'||e.key==='w'||e.key==='W')keys.jump=false}
window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',()=>{keys.left=keys.right=keys.jump=false});
let paused=false;function togglePause(){paused=!paused;message(paused?'PAUSED · press ESC to return':'');if(paused){keys.left=keys.right=keys.jump=false}}
document.getElementById('startBtn').onclick=()=>{ui.start.classList.add('hidden');started=true;last=performance.now();sound(330,.22,'sine',.035)};
document.getElementById('againBtn').onclick=()=>{ui.end.classList.add('hidden');fresh();started=true;last=performance.now()};
document.getElementById('soundBtn').onclick=e=>{muted=!muted;e.currentTarget.textContent=muted?'♪':'♫';if(!muted)sound(440)};
document.querySelectorAll('.touch-btn').forEach(btn=>{const action=btn.dataset.key;const down=e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);if(action==='left')keys.left=true;if(action==='right')keys.right=true;if(action==='jump'){if(!keys.jump)jump();keys.jump=true}if(action==='transform')transform()},up=e=>{e.preventDefault();if(action==='left')keys.left=false;if(action==='right')keys.right=false;if(action==='jump')keys.jump=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up)});
function collisionUpdate(dt){const p=player;let dir=(keys.right?1:0)-(keys.left?1:0);p.vx+=(dir* (p.form==='phoenix'?940:1300))*dt;p.vx*=Math.pow(dir?.82:.0007,dt);p.vx=clamp(p.vx,-(p.form==='phoenix'?295:250),(p.form==='phoenix'?295:250));if(dir)p.facing=dir;p.x+=p.vx*dt;
if(p.form==='phoenix'){p.vy+= (keys.jump?90:230)*dt;p.energy-=dt*(keys.jump?10:4.7);if(p.energy<=0){p.energy=0;p.form='human';message('Your wings need another ember');burst(p.x+17,p.y+22,'#ffb457',18);flash();sound(130,.4,'sawtooth',.03)}}else p.vy+=1480*dt;
p.y+=p.vy*dt;p.ground=false;
for(const plat of platforms){if(p.x+p.w>plat.x&&p.x<plat.x+plat.w&&p.y+p.h>=plat.y&&p.y+p.h-p.vy*dt<=plat.y&&p.vy>=0){p.y=plat.y-p.h;p.vy=0;p.ground=true}}
if(p.form==='phoenix'&&p.y+p.h>605&&platforms.some(q=>q.y===605&&p.x+p.w>q.x&&p.x<q.x+q.w)){p.y=557;p.vy=0;p.ground=true}
p.x=clamp(p.x,0,worldEnd-45);if(p.y>820)hurt(true);
for(const e of embers){if(e.taken)continue;const dx=p.x+p.w/2-e.x,dy=p.y+p.h/2-e.y;if(dx*dx+dy*dy<42*42){e.taken=true;p.energy=Math.min(100,p.energy+34);burst(e.x,e.y,'#ffe19a',26);sound(580,.18,'sine',.045);setTimeout(()=>sound(780,.24,'sine',.025),65);updateHud();message(`Ember kindled · ${embers.filter(v=>v.taken).length} of 6`)}}
for(const h of hazards){if(!h.active)continue;let hx=h.x+Math.sin(worldTime*h.speed+h.phase)*h.range,hy=h.base+Math.sin(worldTime*2+h.phase)*12;if(Math.abs(p.x+p.w/2-hx)<32&&Math.abs(p.y+p.h/2-hy)<37&&p.invuln<=0)hurt(false)}
if(p.invuln>0)p.invuln-=dt;let checkpointAt=[0,1180,2520,3270].filter(x=>p.x>x).length;if(checkpointAt>checkpoint){checkpoint=checkpointAt;p.checkpoint=[0,1180,2520,3270][checkpointAt];message('A cinder shrine remembers you');burst(p.x,p.y+24,'#78d8cd',12)}
if(p.x>worldEnd-150){if(embers.filter(e=>e.taken).length>=6)win();else if(Math.floor(worldTime*2)%4===0)message('The Sun Gate needs all six embers')}
}
function hurt(fall){if(player.invuln>0)return;player.lives--;player.invuln=1.6;burst(player.x+17,player.y+22,'#d76f74',24);sound(100,.3,'sawtooth',.04);if(player.lives<=0){lose();return}if(fall){player.x=player.checkpoint+36;player.y=555}else{player.vy=-320;player.vx=-player.facing*190;if(player.form==='phoenix')player.energy=Math.max(15,player.energy-20)}updateHud();message('The dark cannot keep you · one more chance')}
function win(){if(ended)return;ended=true;burst(player.x+20,player.y+12,'#ffd77e',90);flash();sound(520,.8,'sine',.05);ui.end.classList.remove('hidden');document.getElementById('endEyebrow').textContent='The valley remembers';document.getElementById('endTitle').innerHTML='A NEW DAWN<span>THE FIRE LIVES ON</span>';document.getElementById('endDesc').textContent='You gathered every ember and woke the Sun Gate. Mortal, flame, and sky are one again.'}
function lose(){ended=true;ui.end.classList.remove('hidden');document.getElementById('endEyebrow').textContent='Even ash can bloom';document.getElementById('endTitle').innerHTML='THE FIRE WAITS<span>NO ENDING IS FINAL</span>';document.getElementById('endDesc').textContent='The valley is still here. The embers are still waiting. Rise, and try again.'}

