function lose(){ended=true;ui.end.classList.remove('hidden');document.getElementById('endEyebrow').textContent='Even ash can bloom';document.getElementById('endTitle').innerHTML='THE FIRE WAITS<span>NO ENDING IS FINAL</span>';document.getElementById('endDesc').textContent='The valley is still here. The embers are still waiting. Rise, and try again.'}

function path(points,fill,stroke=null,width=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#17152a');g.addColorStop(.48,'#493044');g.addColorStop(.78,'#b45f48');g.addColorStop(1,'#e39757');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
const sunX=W*.73-camera*.035;const glow=ctx.createRadialGradient(sunX,330,4,sunX,330,230);glow.addColorStop(0,'rgba(255,209,139,.52)');glow.addColorStop(.4,'rgba(246,139,92,.18)');glow.addColorStop(1,'rgba(242,112,83,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-240,90,480,480);ellipse(sunX,330,54,54,'#ffd7a0');ellipse(sunX,330,72,72,'rgba(255,207,142,.15)');
for(let i=0;i<70;i++){let x=((i*197+53-camera*.08)%(W+80)+W+80)%(W+80)-40,y=30+(i*83%290);ellipse(x,y,(i%3)*.35+0.7,(i%3)*.35+0.7,`rgba(255,229,199,${.18+(i%5)*.09})`)}
// distant ridges
for(let layer=0;layer<3;layer++){let base=470+layer*52,shift=camera*(.07+layer*.045),step=180;ctx.beginPath();ctx.moveTo(-step,base+150);for(let i=-1;i<Math.ceil(W/step)+3;i++){let x=i*step-(shift%step),peak=base-70-((i*37+layer*59)%110);ctx.lineTo(x,base);ctx.lineTo(x+step*.48,peak);ctx.lineTo(x+step,base+15)}ctx.lineTo(W+300,H);ctx.lineTo(-300,H);ctx.closePath();ctx.fillStyle=['#382d43','#30273a','#272435'][layer];ctx.fill()}
// floating cinder motes
for(let i=0;i<22;i++){let x=(i*173-camera*.19)%(W+30);if(x<0)x+=W+30;let y=300+(i*67%280)+Math.sin(worldTime*.8+i)*12;ellipse(x,y,1.3,1.3,'rgba(255,175,104,.58)')}}
function drawRuins(){ctx.save();ctx.translate(-camera*.32,0);for(let i=0;i<7;i++){let x=160+i*620;ctx.globalAlpha=.48;ctx.fillStyle='#241f31';ctx.fillRect(x,423,25,170);ctx.fillRect(x-13,415,51,13);ctx.fillRect(x+5,455,9,23);ctx.fillStyle='#ef9871';ctx.globalAlpha=.35;ellipse(x+12,440,2,2,'#ffc98d');}ctx.globalAlpha=1;
// broken arch silhouette
for(let i=0;i<4;i++){let x=500+i*1000;ctx.fillStyle='#282235';ctx.fillRect(x,400,18,195);ctx.fillRect(x-12,392,42,12);ctx.fillRect(x+100,438,18,157);ctx.fillRect(x+91,430,36,12);ctx.fillRect(x,398,117,13);ctx.fillRect(x+48,411,15,28)}ctx.restore()}
function drawGround(){for(const p of platforms){let sx=p.x-camera;if(sx+p.w<-80||sx>W+80)continue;const isFloor=p.y===605;ctx.fillStyle=isFloor?'#211d2b':'#302332';ctx.fillRect(sx,p.y,p.w,H-p.y+100);ctx.fillStyle=isFloor?'#58404a':'#6f4a49';ctx.fillRect(sx,p.y,p.w,5);ctx.fillStyle='#e49b64';ctx.globalAlpha=.42;ctx.fillRect(sx,p.y,p.w,2);ctx.globalAlpha=1;
// strata and sparse moss
for(let j=0;j<Math.ceil(p.w/44);j++){let x=sx+j*44+((j*7)%13),y=p.y+19+(j*31%70);ctx.fillStyle=j%3?'#3b2a34':'#493039';ctx.fillRect(x,y,18+(j*11%21),2)}if(!isFloor){ctx.fillStyle='#bf795b';for(let j=0;j<p.w/35;j++){let x=sx+j*35+8;ctx.fillRect(x,p.y-2,3,3)}}}}
function drawEmber(e){if(e.taken)return;let x=e.x-camera,y=e.y+Math.sin(worldTime*2.7+e.x)*6;ctx.save();ctx.translate(x,y);ctx.rotate(worldTime*.55);ctx.shadowColor='#ffc768';ctx.shadowBlur=22;path([[0,-12],[7,-3],[0,11],[-7,-3]],'#ffe0a0');ctx.shadowBlur=0;ctx.rotate(-worldTime*1.1);ellipse(0,0,2,4,'#fff7d8');ctx.restore();ellipse(x,y+15,12,2,'rgba(255,183,102,.2)')}
function drawHazard(h){if(!h.active)return;let x=h.x+Math.sin(worldTime*h.speed+h.phase)*h.range-camera,y=h.base+Math.sin(worldTime*2+h.phase)*12;ctx.save();ctx.translate(x,y);ctx.shadowColor='#ff613e';ctx.shadowBlur=17;ellipse(0,0,13,13,'#c34e4b');ctx.shadowBlur=0;ellipse(-4,-4,4,4,'#ffc07c');ellipse(5,3,3,3,'#46283c');ctx.strokeStyle='#ff9d59';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,17,worldTime*2,worldTime*2+2.7);ctx.stroke();ctx.restore()}
function drawGate(){let x=worldEnd-90-camera;if(x<-100||x>W+100)return;ctx.save();ctx.translate(x,0);let lit=embers.filter(e=>e.taken).length>=6;ctx.shadowColor=lit?'#ffe09b':'#c77d5e';ctx.shadowBlur=lit?42:16;ctx.strokeStyle=lit?'#ffd88a':'#a87568';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(-55,605);ctx.lineTo(-55,450);ctx.quadraticCurveTo(-55,330,0,330);ctx.quadraticCurveTo(55,330,55,450);ctx.lineTo(55,605);ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#f8c685';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-38,605);ctx.lineTo(-38,450);ctx.quadraticCurveTo(-38,350,0,350);ctx.quadraticCurveTo(38,350,38,450);ctx.lineTo(38,605);ctx.stroke();if(lit){let g=ctx.createRadialGradient(0,470,5,0,470,75);g.addColorStop(0,'rgba(255,238,183,.92)');g.addColorStop(.35,'rgba(255,195,112,.58)');g.addColorStop(1,'rgba(255,175,94,0)');ctx.fillStyle=g;ctx.fillRect(-90,370,180,200)}else{ctx.fillStyle='#ffd7a0';ctx.font='10px Cinzel,serif';ctx.textAlign='center';ctx.fillText('S U N   G A T E',0,320)}ctx.restore()}

